function cookies(req: Request) {
  return Object.fromEntries((req.headers.get("cookie") || "").split(";").map(v => {
    const i = v.indexOf("="); return i < 0 ? ["", ""] : [v.slice(0, i).trim(), decodeURIComponent(v.slice(i + 1))];
