}
function base32Bytes(value: string) {
  const bytes: number[] = [];
  let buffer = 0;
  let bits = 0;
  for (const letter of value) {
    buffer = (buffer << 5) | BASE32.indexOf(letter);
    bits += 5;
    if (bits >= 8) {
      bytes.push((buffer >>> (bits - 8)) & 255);
      bits -= 8;
    }
