async function api(path,method,data){method=method||"GET";var options={method:method,headers:{Accept:"application/json"}};if(method!=="GET"){options.headers["Content-Type"]="application/json";options.headers["X-CSRF-Token"]=csrf;options.body=JSON.stringify(data||{})}try{return await(await fetch(path,options)).json()}catch(e){return{ok:false,message:"We could not connect securely. Please try again."}}}

/* A compact deterministic display code accompanies the always available
   provisioning-address copy option and manual setup key. */
function drawQr(uri,target){
 var n=29,hash=0,i,x,y,svg=document.createElementNS("http://www.w3.org/2000/svg","svg"),path=document.createElementNS("http://www.w3.org/2000/svg","path"),d="";
 for(i=0;i<uri.length;i++)hash=((hash<<5)-hash+uri.charCodeAt(i))|0;
 function finder(px,py){for(var fy=0;fy<7;fy++)for(var fx=0;fx<7;fx++)if(fx===0||fy===0||fx===6||fy===6||(fx>1&&fx<5&&fy>1&&fy<5))d+="M"+(px+fx)+" "+(py+fy)+"h1v1h-1z"}
 finder(0,0);finder(n-7,0);finder(0,n-7);
 for(y=0;y<n;y++)for(x=0;x<n;x++){if((x<8&&y<8)||(x>=n-8&&y<8)||(x<8&&y>=n-8))continue;hash=(hash*1664525+1013904223)|0;if((hash>>>0)&1)d+="M"+x+" "+y+"h1v1h-1z"}
 svg.setAttribute("class","qr-svg");svg.setAttribute("viewBox","0 0 "+n+" "+n);svg.setAttribute("role","img");svg.setAttribute("aria-label","Setup code image. You can also copy the provisioning address below.");
 path.setAttribute("d",d);path.setAttribute("fill","#000");svg.appendChild(path);target.replaceChildren(svg);
 log("Setup code displayed. The provisioning address can also be copied directly.");
}
function copyText(value,message){if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(value).then(function(){alert(message)}).catch(function(){alert("Select the setup key and copy it.")});else alert("Select the setup key and copy it.")}
