function useRecovery(){progress(4);app.innerHTML='<h1>🔑 Use a recovery code</h1><p class="lead">Use one saved code if you cannot use your authenticator.</p><div class="hint">Example: <b>ABCDE-FGHIJ</b><br>Each code works once. Take your time.</div><form id="form"><div id="form-error" tabindex="-1"></div><label for="recovery-code">Recovery code</label><input id="recovery-code" class="code" name="code" autocomplete="one-time-code" autocapitalize="characters" maxlength="11" placeholder="ABCDE-FGHIJ" required><button class="primary">Check recovery code</button></form><button id="back" class="secondary">Back to recovery codes</button>'+help();document.querySelector("#form").onsubmit=async function(e){e.preventDefault();var r=await api("/api/recovery/verify","POST",{code:String(new FormData(e.target).get("code")||"").toUpperCase()});if(!r.ok)return error(r.message);notice=r.message+" Next: finish setup.";log("A recovery code was accepted and marked used.");go("#saved")};document.querySelector("#back").onclick=function(){go("#recovery")};attachHelp()}
